def _validate_metric_lengths(
    expected_samples: int,
    confidence: np.ndarray,
    uncertainty: np.ndarray,
    ood_scores: np.ndarray,
    ood_flags: np.ndarray,
) -> None:
    """Ensure all reliability metrics contain one value per sample."""
    metrics = {
        "confidence": confidence,
        "uncertainty": uncertainty,
        "OOD scores": ood_scores,
        "OOD flags": ood_flags,
    }

    for name, values in metrics.items():
        if values.ndim != 1:
            raise PredictionError(
                f"{name} must contain one value per sample."
            )

        if len(values) != expected_samples:
            raise PredictionError(
                f"{name} contains {len(values)} values, "
                f"but {expected_samples} samples were predicted."
            )

def _get_ood_threshold(self) -> float:
    """Return and validate the configured OOD threshold."""
    try:
        threshold = float(self.ood.threshold)
    except (TypeError, ValueError) as exc:
        raise PredictionError(
            "OOD detector threshold must be numeric."
        ) from exc

    if not np.isfinite(threshold) or threshold <= 0.0:
        raise PredictionError(
            "OOD detector threshold must be greater than zero."
        )

    return threshold

def _normalize_ood_score(
    raw_score: float,
    threshold: float,
) -> float:
    """
    Convert an unbounded OOD distance into [0, 1] risk.

    Values at or above the configured threshold represent
    maximum normalized OOD risk.
    """
    if not np.isfinite(raw_score):
        raise PredictionError(
            "OOD detector returned a NaN or infinite score."
        )

    if raw_score < 0.0:
        raise PredictionError(
            "OOD detector returned a negative score."
        )

    return float(
        min(
            raw_score / threshold,
            1.0,
        )
    )

def _to_python_value(
    value: Any,
) -> Any:
    """Convert NumPy scalar values into native Python values."""
    if isinstance(value, np.generic):
        return value.item()

    return value

def to_dict(self) -> dict[str, Any]:
    """Return the report as a Python dictionary."""
    return self.model_dump()

def to_json(
    self,
    indent: int = 4,
) -> str:
    """Return the report as formatted JSON.

    Args:
        indent:
            Number of spaces used for JSON indentation.

    Returns:
        JSON representation of the report.
    """
    if indent < 0:
        raise ValueError(
            "JSON indentation cannot be negative."
        )

    return self.model_dump_json(
        indent=indent,
    )

def __str__(self) -> str:
    """Return the report as formatted JSON."""
    return self.to_json()

def __call__(
    self,
    current_data: Any,
) -> bool:
    """
    Callable interface.
    """
    return self.detect(current_data)

def __repr__(self) -> str:
    return (
        f"{self.__class__.__name__}("
        f"threshold={self.threshold})"
    )

def summary(
    self,
    current_predictions: Any,
) -> dict[str, Any]:
    """
    Return a summary of concept drift.
    """
    score = self.score(current_predictions)

    return {
        "drift_score": score,
        "drift_detected": score > self.threshold,
        "reference_samples": len(self.reference_data),
        "current_samples": len(
            np.asarray(current_predictions).flatten()
        ),
    }

def score(
    self,
    current_data: Any,
) -> float:
    """
    Compute the drift score.

    Returns:
        Drift score in [0,1].

        Higher score = more drift.
    """
    if not self.is_fitted:
        raise RuntimeError(
            "Detector must be fitted first."
        )

    current = np.asarray(current_data)

    if current.ndim == 1:
        current = current.reshape(-1, 1)

    p_values = []

    for feature in range(self.reference_data.shape[1]):
        _, p_value = ks_2samp(
            self.reference_data[:, feature],
            current[:, feature],
        )

        p_values.append(p_value)

    min_p = float(min(p_values))

    # Convert p-value into drift score.
    drift_score = 1.0 - min_p

    return float(
        np.clip(drift_score, 0.0, 1.0)
    )

def feature_scores(
    self,
    current_data: Any,
) -> dict[int, float]:
    """
    Compute drift score for every feature individually.

    Returns:
        Mapping:
            feature_index -> drift_score
    """
    if not self.is_fitted:
        raise RuntimeError(
            "Detector must be fitted first."
        )

    current = np.asarray(current_data)

    if current.ndim == 1:
        current = current.reshape(-1, 1)

    scores = {}

    for feature in range(self.reference_data.shape[1]):
        _, p = ks_2samp(
            self.reference_data[:, feature],
            current[:, feature],
        )

        scores[feature] = float(
            np.clip(1.0 - p, 0.0, 1.0)
        )

    return scores

def summary(
    self,
    current_data: Any,
) -> dict[str, Any]:
    """
    Return a drift summary.
    """
    score = self.score(current_data)

    return {
        "drift_score": score,
        "drift_detected": score > self.threshold,
        "feature_scores": self.feature_scores(
            current_data
        ),
    }

def drift_summary(
    reference: np.ndarray,
    current: np.ndarray,
) -> dict[str, float]:
    """
    Compute multiple drift metrics at once.
    """
    return {
        "kl_divergence": kl_divergence(reference, current),
        "js_divergence": jensen_shannon_divergence(reference, current),
        "wasserstein": wasserstein(reference, current),
    }

def validate_input(
    self,
    X: ModelInput,
) -> np.ndarray:
    """
    Convert and validate model input.

    The returned value is always a two-dimensional finite
    float64 NumPy array.

    Args:
        X:
            Input samples.

    Returns:
        Array with shape ``(n_samples, n_features)``.

    Raises:
        OODDetectionError:
            If the input cannot be converted to a valid
            feature matrix.
    """
    try:
        values = np.asarray(X, dtype=np.float64)
    except (TypeError, ValueError) as exc:
        raise OODDetectionError(
            "OOD input must contain numeric feature values."
        ) from exc

    if values.ndim == 1:
        values = values.reshape(1, -1)

    if values.ndim != 2:
        raise OODDetectionError(
            "Expected input of shape "
            "(n_samples, n_features)."
        )

    n_samples, n_features = values.shape

    if n_samples == 0:
        raise OODDetectionError(
            "OOD input cannot contain zero samples."
        )

    if n_features == 0:
        raise OODDetectionError(
            "OOD input must contain at least one feature."
        )

    if not np.all(np.isfinite(values)):
        raise OODDetectionError(
            "OOD input cannot contain NaN or infinite values."
        )

    return values

def __call__(self, X: ModelInput) -> np.ndarray:
    """Shortcut for ``predict(X)``."""
    return self.predict(X)

def __repr__(self) -> str:
    """Return a developer-friendly representation."""
    return (
        f"{self.__class__.__name__}("
        f"name='{self.name}', "
        f"fitted={self.is_fitted})"
    )

def name(self) -> str:
    """Return the detector name."""
    return "Z-Score OOD Detector"

def is_fitted(self) -> bool:
    """Return whether the detector has been fitted."""
    return (
        self._mean is not None
        and self._std is not None
        and self._n_features is not None
    )

def score(self, X: ModelInput) -> np.ndarray:
    """Compute the raw OOD distance for each sample.

    Args:
        X:
            Input samples.

    Returns:
        One unbounded raw OOD score per sample.

    Raises:
        OODDetectionError:
            If the detector is not fitted or the input is invalid.
    """
    self.require_fitted()

    values = self.validate_input(X)

    if self._n_features is None:
        raise OODDetectionError(
            "Detector feature configuration is unavailable."
        )

    self.validate_feature_count(
        values,
        self._n_features,
    )

    if self._mean is None or self._std is None:
        raise OODDetectionError(
            "Detector parameters are unavailable."
        )

    z_scores = np.abs(
        (values - self._mean) / self._std
    )

    raw_scores = np.max(
        z_scores,
        axis=1,
    )

    if not np.all(np.isfinite(raw_scores)):
        raise OODDetectionError(
            "OOD calculation produced NaN or infinite scores."
        )

    return raw_scores.astype(
        np.float64,
        copy=False,
    )

def __repr__(self) -> str:
    """Return a developer-friendly representation."""
    return (
        f"{self.__class__.__name__}("
        f"threshold={self.threshold}, "
        f"is_fitted={self.is_fitted})"
    )

class RecommendationEngine:
    """
    Generate risk levels and recommendations from trust scores.

    The configured thresholds define the decision policy:

        trust >= auto_approve_threshold
            -> LOW risk
            -> AUTO_APPROVE

        trust >= review_threshold
            -> MEDIUM risk
            -> HUMAN_REVIEW

        trust < review_threshold
            -> HIGH risk
            -> REJECT
    """

    def __init__(
        self,
        auto_approve_threshold: float | None = None,
        review_threshold: float | None = None,
    ) -> None:
        """Initialize the recommendation policy.

        Args:
            auto_approve_threshold:
                Minimum trust score for automatic approval.
                Defaults to the configured value.

            review_threshold:
                Minimum trust score for human review.
                Defaults to the configured value.

        Raises:
            ValidationError:
                If thresholds are invalid or inconsistent.
        """
        self.auto_approve_threshold = self._validate_threshold(
            (
                settings.auto_approve_threshold
                if auto_approve_threshold is None
                else auto_approve_threshold
            ),
            "auto_approve_threshold",
        )

        self.review_threshold = self._validate_threshold(
            (
                settings.review_threshold
                if review_threshold is None
                else review_threshold
            ),
            "review_threshold",
        )

        if self.review_threshold >= self.auto_approve_threshold:
            raise ValidationError(
                "review_threshold must be lower than "
                "auto_approve_threshold."
            )

    def recommend(
        self,
        trust_score: float,
    ) -> Recommendation:
        """
        Generate a recommendation from a trust score.

        Args:
            trust_score:
                Trust score in the range [0, 1].

        Returns:
            Recommendation enum.
        """
        score = self._validate_trust_score(trust_score)

        if score >= self.auto_approve_threshold:
            return Recommendation.AUTO_APPROVE

        if score >= self.review_threshold:
            return Recommendation.HUMAN_REVIEW

        return Recommendation.REJECT

    def risk_level(
        self,
        trust_score: float,
    ) -> RiskLevel:
        """
        Determine the risk level associated with a trust score.

        Args:
            trust_score:
                Trust score in the range [0, 1].

        Returns:
            RiskLevel enum.
        """
        score = self._validate_trust_score(trust_score)

        if score >= self.auto_approve_threshold:
            return RiskLevel.LOW

