def test_binary_confidence(estimator):
    probabilities = np.array(
        [
            [0.10, 0.90],
            [0.60, 0.40],
        ]
    )

    result = estimator.compute(probabilities)

    np.testing.assert_allclose(
        result,
        [0.90, 0.60],
    )

